-- PBI-010: los adicionales son un tipo de producto con precio propio.
insert into public.tipos_productos ("Descripcion")
values ('Adicional')
on conflict ("Descripcion") do nothing;

-- PBI-005 y RN-014: insumos que un servicio consume al aplicarse.
create table if not exists public.servicios_insumos (
  "Id_Servicios_Insumos" integer generated by default as identity primary key,
  "Id_Servicios" integer not null references public.productos("Id_Productos") on delete cascade,
  "Id_Insumos" integer not null references public.productos("Id_Productos") on delete restrict,
  "Cantidad" numeric(18,0) not null check ("Cantidad" > 0),
  constraint servicios_insumos_unico unique ("Id_Servicios", "Id_Insumos"),
  constraint servicios_insumos_distintos check ("Id_Servicios" <> "Id_Insumos")
);
